4	// Package readingtime provides a function to estimate the reading time of an article.
5	package readingtime
6	
7	import (
8		"strings"
9		"unicode"
10		"unicode/utf8"
11	
12		"miniflux.app/v2/internal/reader/sanitizer"
13	)
14	
15	// EstimateReadingTime returns the estimated reading time of an article in minute.
16	func EstimateReadingTime(content string, defaultReadingSpeed, cjkReadingSpeed int) int {
17		const truncationPoint = 100
18	
19		sanitizedContent := sanitizer.StripTags(content)
20	
21		if isCJK(sanitizedContent, truncationPoint) {
22			return (utf8.RuneCountInString(sanitizedContent) + cjkReadingSpeed - 1) / cjkReadingSpeed
23		}
24	
25		return (countWords(sanitizedContent) + defaultReadingSpeed - 1) / defaultReadingSpeed
26	}
27	
28	func countWords(s string) int {
29		n := 0
30		for range strings.FieldsSeq(s) {
31			n++
32		}
33		return n
34	}
35	
36	func isCJK(text string, limit int) bool {
37		var letters, totalCJK int
38		for _, r := range text {
39			// Numbers and control characters often used in CJK too.
40			// Counting them makes detection less reliable.
41			if !unicode.In(r, unicode.Letter) {
42				continue
43			}
44	
45			if letters++; letters == limit {
46				break
47			}
48	
49			if unicode.In(r, unicode.Han, unicode.Hangul, unicode.Hiragana, unicode.Katakana, unicode.Yi, unicode.Bopomofo) {
50				totalCJK++
51			}
52		}
53	
54		// If at least half of the letters is CJK, odds are that the text is CJK.
55		midpoint := letters / 2
56	
57		return totalCJK > midpoint
58	}
